  /* Páginas de formulários: prévia textual e consentimento, sem persistir dados de contato. */
  function initAdvertise() {
    const form=$('#advertise-form');form.addEventListener('submit',event=>{event.preventDefault();const fields=form.elements;const phone=fields.phone.value.replace(/\D/g,'');const error=phone.length<10||phone.length>15?'Informe um telefone demonstrativo com 10 a 15 dígitos.':fields.name.value.trim().length<2?'Informe um nome fictício válido.':'';$('#advertise-error').textContent=error;if(error)return;const text=['SOLICITAÇÃO DEMONSTRATIVA — ANUNCIAR IMÓVEL',`Nome fictício: ${fields.name.value.trim()}`,`E-mail fictício: ${fields.email.value.trim()}`,`WhatsApp fictício: ${fields.phone.value.trim()}`,`Região: ${fields.city.value.trim()} / ${fields.district.value.trim()}`,`Tipo: ${fields.type.value}`,`Finalidade: ${fields.purpose.value}`,`Valor pretendido: ${money(Number(fields.price.value))}`,`Descrição: ${fields.description.value.trim()}`,`Fotografias: ${fields.photos.value}`,'Prévia local, não enviada. Nenhum anúncio publicado e nenhuma fotografia transmitida.'].join('\n');$('#advertise-text').textContent=text;$('#advertise-preview').hidden=false;const href=whatsappHref(text);$('#advertise-send').hidden=!href;if(href)$('#advertise-send').href=href;$('#advertise-preview').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'nearest'});}); // Nenhum POST ou backend é simulado.
    form.addEventListener('input',()=>{$('#advertise-preview').hidden=true;});form.addEventListener('change',()=>{$('#advertise-preview').hidden=true;}); // Não deixa uma prévia antiga parecer atual depois de editar os campos.
    $('#advertise-copy').addEventListener('click',async()=>notify(await copyText($('#advertise-text').textContent)?'Solicitação copiada. Não foi enviada nem publicada.':'Selecione o texto da prévia e copie manualmente.')); // Copiar não equivale a encaminhar.
  }
  function initSimulator() {
    const form=$('#loan-form');const value=Number(new URLSearchParams(location.search).get('value'));if(Number.isFinite(value)&&value>0&&value<=1e8){form.elements.value.value=value;form.elements.deposit.value=Math.round(value*.2);} // Entrada inicial ilustrativa, não exigência bancária.
    form.addEventListener('submit',event=>{event.preventDefault();const value=Number(form.elements.value.value),deposit=Number(form.elements.deposit.value),months=Number(form.elements.months.value),annual=Number(form.elements.rate.value);const error=![value,deposit,months,annual].every(Number.isFinite)?'Revise os valores numéricos.':deposit>=value?'A entrada deve ser menor que o valor do imóvel.':deposit<0||value<=0||months<1||months>600||!Number.isInteger(months)||annual<0||annual>100?'Revise entrada, prazo e juros informados.':'';$('#loan-error').textContent=error;if(error)return;const principal=value-deposit,monthly=Math.expm1(Math.log1p(annual/100)/12),payment=monthly===0?principal/months:principal*monthly/(-Math.expm1(-months*Math.log1p(monthly))),total=payment*months; // Taxa anual efetiva convertida à equivalente mensal; tratamento exato para juros zero.
      const root=$('#loan-result');root.replaceChildren(el('p','ESTIMATIVA MATEMÁTICA / SISTEMA PRICE','eyebrow light'),el('h2','Um ponto de partida.'),el('p','Prestação mensal estimada, sem custos adicionais'),el('strong',money(payment)));const facts=el('div',undefined,'loan-facts');[['Valor financiado',money(principal)],['Prazo',`${months} meses`],['Taxa anual efetiva informada',`${annual.toLocaleString('pt-BR')}%`],['Equivalente mensal',`${(monthly*100).toLocaleString('pt-BR',{maximumFractionDigits:5})}%`],['Total das parcelas',money(total)],['Juros matemáticos no prazo',money(Math.max(0,total-principal))]].forEach(([label,value])=>{const row=el('div');row.append(el('span',label),el('span',value));facts.append(row);});root.append(facts,el('p','Não é proposta bancária, aprovação ou simulação oficial. Seguros, tarifas, tributos, correção monetária e demais despesas não estão incluídos. O custo real e a elegibilidade dependem da análise da operação.','legal')); // Não extrapola cálculo para crédito ou MCMV.
    }); // Nenhum documento ou dado de renda é solicitado.
  }
  function renderBrokers() { const records=read('brokers',D.brokers);const brokers=Array.isArray(records)?records:D.brokers;$('#brokers-grid').replaceChildren(...brokers.slice(0,20).map((b,index)=>{const item=el('article',undefined,'broker-card');const figure=el('div');const image=el('img');const allowed=D.brokers.some(p=>p.photo===Number(b.photo))?Number(b.photo):D.brokers[index%D.brokers.length].photo;image.src=`assets/img/${allowed}.webp`;image.alt='Retrato ilustrativo de banco; não representa o profissional fictício apresentado';image.width=700;image.height=850;image.loading='lazy';figure.append(image,el('span','RETRATO DE BANCO • PERSONAGEM FICTÍCIO','photo-tag'));const body=el('div',undefined,'broker-copy');body.append(el('small','APRESENTAÇÃO DEMONSTRATIVA'),el('h2',cleanText(b.name,80)||'Profissional de exemplo'),el('p',cleanText(b.specialty,120)),el('p',cleanText(b.region,120)),el('p','CRECI: a configurar e verificar em uma operação real.'),button('PREPARAR CONVERSA ↗',()=>openContact(`Contato demonstrativo com ${cleanText(b.name,80)}`,null,false,null,/^\d{10,15}$/.test(b.whatsapp||'')?b.whatsapp:''),'button outline-button'));item.append(figure,body);return item;})); } // Nunca inventa ou atribui um número de CRECI.

