  if(page==='brokers')renderBrokers(); // Equipe declaradamente fictícia.
  if(page==='advertise')initAdvertise(); // Preview sem envio.
  if(page==='simulator')initSimulator(); // Cálculo Price.
  if(page==='contact')$('#contact-page-form').addEventListener('submit',event=>{event.preventDefault();const f=event.currentTarget;openContact(f.elements.subject.value);showMessage(`CONVERSA DEMONSTRATIVA\nNome fictício: ${f.elements.name.value.trim()}\nAssunto: ${f.elements.subject.value}\nMensagem: ${f.elements.message.value.trim()}\nPrévia local. Nada enviado; nenhum atendimento ou agendamento confirmado.`);}); // O contato não solicita e-mail, CPF ou documentos.
  syncSelections();showStorageWarning(); // Atualiza contadores mesmo em páginas sem cards.
  window.VP={D,$,$$,el,link,button,money,read,write,removeStored,notify,confirmAction,allListings,sanitizeListing,today,renderCards}; // API mínima para o painel local, sem acesso privilegiado real.
